tool_input.command:
python3 -c "
from databricks.sdk import WorkspaceClient
w = WorkspaceClient()
run = w.jobs.get_run(run_id=596143413667176)
print('Tasks:', len(run.tasks) if run.tasks else 0)
if run.tasks:
    for t in run.tasks:
        print(f'  Task {t.task_key}: run_id={t.run_id} state={t.state}')
        if t.run_id:
            try:
                out = w.jobs.get_run_output(run_id=t.run_id)
                if out.error:
                    print(f'  Error: {out.error}')
                if out.error_trace:
                    print(f'  Trace (first 1000): {out.error_trace[:1000]}')
                if out.logs:
                    print(f'  Logs: {out.logs[:500]}')
            except Exception as ex:
                print(f'  Output error: {ex}')
" 2>&1
